"""Local-disk artifact storage. Keys are generated by the server (never taken from user input) and
every path is checked to stay inside the storage root. Swap this class for blob storage in production."""
from __future__ import annotations

import re
from pathlib import Path

from app.core.config import get_settings

_KEY = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/\- ]{0,400}$")


class LocalStorage:
    def __init__(self, root: str | Path | None = None) -> None:
        self.root = Path(root or get_settings().storage_dir).resolve()

    def path_for(self, key: str) -> Path:
        if not _KEY.match(key) or ".." in key.split("/") or key.startswith("/"):
            raise ValueError("invalid storage key")
        p = (self.root / key).resolve()
        if self.root != p and self.root not in p.parents:
            raise ValueError("storage key escapes the storage root")
        return p

    def new_temp(self) -> Path:
        tmp = self.root / "tmp"
        tmp.mkdir(parents=True, exist_ok=True)
        import uuid
        return tmp / f"{uuid.uuid4().hex}.part"

    def commit(self, tmp: Path, key: str) -> Path:
        dest = self.path_for(key)
        dest.parent.mkdir(parents=True, exist_ok=True)
        tmp.replace(dest)
        return dest

    def write_bytes(self, key: str, data: bytes) -> Path:
        dest = self.path_for(key)
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
        return dest

    def exists(self, key: str) -> bool:
        try:
            return self.path_for(key).is_file()
        except ValueError:
            return False

    def delete(self, key: str) -> None:
        try:
            self.path_for(key).unlink(missing_ok=True)
        except ValueError:
            pass
